INSERT IGNORE INTO `projects` (`project_id`, `title`, `fiscal_year`, `strategy_id`, `agency_id`, `status`, `progress`, `budget_allocated`, `budget_used`, `target_quantitative`, `operated_activities`) VALUES
-- ยุทธศาสตร์ที่ 1 (16 โครงการ)
('PRJ2569-001', 'โครงการมหกรรมสัปดาห์วิทยาศาสตร์ (Science Week INNOTECH 2026)', '2569', 1, 8, 'ยังไม่เริ่ม', 0, 160000.00, 0.00, 'ครู นักศึกษา สกร. และเยาวชน จำนวน 500 คน', 'ประชุมเตรียมความพร้อม, จัดกิจกรรมมหกรรมฯ, ประชุมถอดบทเรียน'),
('PRJ2569-002', 'โครงการ Narasci โครงงานวิทยาศาสตร์สร้างสรรค์สู่ชุมชน', '2569', 1, 8, 'ยังไม่เริ่ม', 0, 160000.00, 0.00, 'ครู นักศึกษา สกร. และเยาวชน จำนวน 280 คน', 'อบรมทำโครงงาน, ประกวดระดับพื้นที่, ถอดบทเรียน, ประกวดระดับประเทศ'),
('PRJ2569-003', 'โครงการส่งเสริมทักษะวิชาวิทยาศาสตร์ คณิตศาสตร์ อังกฤษให้ ม.3 ห้องเรียนสาธิต', '2569', 1, 9, 'ยังไม่เริ่ม', 0, 100000.00, 0.00, 'นักเรียน ม.3 ห้องเรียนสาธิต จำนวน 25 คน', 'กิจกรรมส่งเสริมทักษะวิทย์ คณิต และภาษาอังกฤษ'),
('PRJ2569-004', 'โครงการสถานพัฒนาเด็กปฐมวัยต้นแบบสุขภาพดี Anak sihat แบบบูรณาการ', '2569', 1, 10, 'ยังไม่เริ่ม', 0, 90675.00, 0.00, 'สถานพัฒนาเด็กปฐมวัย 3 โซน นำร่อง (บาเจาะ แว้ง สุคิริน)', 'สร้างทีม CFT, อบรม Parenting Program, นิเทศติดตาม, แลกเปลี่ยนเรียนรู้'),
('PRJ2569-005', 'โครงการขับเคลื่อนการพัฒนาการจัดการศึกษาปฐมวัยในระดับพื้นที่', '2569', 1, 7, 'ยังไม่เริ่ม', 0, 110000.00, 0.00, 'ครูปฐมวัย ตัวแทนหน่วยงาน 195 คน เด็กปฐมวัย 40,290 คน', 'อบรมจัดทำแผนฯ, อบรมยกระดับคุณภาพด้วยนวัตกรรม, นิเทศติดตาม'),
('PRJ2569-006', 'โครงการเฝ้าระวัง ส่งเสริมสุขภาพและจัดการสุขาภิบาลน้ำสะอาด รร.พระราชดำริ', '2569', 1, 10, 'ยังไม่เริ่ม', 0, 722300.00, 0.00, 'นักเรียนโรงเรียนพระราชดำริ 32 แห่ง', 'ส่งเสริมทันตสุขภาพ, รวมพลคนรักษ์ฟัน, ตรวจคุณภาพน้ำบริโภค'),
('PRJ2569-007', 'โครงการจัดนิทรรศการและแข่งขันทักษะทางวิชาการ', '2569', 1, 11, 'ยังไม่เริ่ม', 0, 100000.00, 0.00, 'ผู้เรียน 300 คน', 'จัดแสดงนิทรรศการ แข่งขันทักษะทางวิชาการ 50 รายการ'),
('PRJ2569-008', 'ดำเนินการทดสอบทางการศึกษาระดับชาติขั้นพื้นฐาน (O-NET) ป.6 และ ม.3', '2569', 1, 7, 'ยังไม่เริ่ม', 0, 66884.00, 0.00, 'นักเรียน ป.6 และ ม.3 จำนวน 722 คน', 'ประชุมชี้แจง, ดำเนินการระดับศูนย์สอบและสนามสอบ'),
('PRJ2569-009', 'โครงการส่งเสริมการเรียนรู้ด้านภาษาเชิงพหุวัฒนธรรม (ไทย มลายู จีน อังกฤษ)', '2569', 1, 11, 'ยังไม่เริ่ม', 0, 100000.00, 0.00, 'นักเรียน รร.เทศบาล 1-4 จำนวน 200 คน', 'เข้าฐานการเรียนรู้ด้านภาษา 4 ภาษา'),
('PRJ2569-010', 'โครงการยกระดับสถานพัฒนาเด็กปฐมวัยจังหวัดนราธิวาส', '2569', 1, 12, 'ยังไม่เริ่ม', 0, 206800.00, 0.00, 'สถานพัฒนาเด็กปฐมวัย 13 อำเภอ ๆ ละ 1 แห่ง', 'อบรม 5-DAY PILA, ลงพื้นที่นิเทศ, ถอดบทเรียนรายงานผล'),
('PRJ2569-011', 'โครงการสนับสนุนค่าใช้จ่ายในการจัดการศึกษาตั้งแต่ระดับอนุบาลจนจบขั้นพื้นฐาน', '2569', 1, 6, 'ยังไม่เริ่ม', 0, 28134351.00, 0.00, 'นักศึกษา สกร. 15,451 คน', 'จัดการเรียนการสอน, จัดซื้อหนังสือเรียน, กิจกรรมพัฒนาผู้เรียน'),
('PRJ2569-012', 'โครงการขับเคลื่อนการดำเนินงาน Thailand Zero Dropout', '2569', 1, 7, 'ยังไม่เริ่ม', 0, 107000.00, 0.00, 'เด็กและเยาวชนนอกระบบการศึกษา', 'บูรณาการค้นหา ติดตาม ช่วยเหลือ และแลกเปลี่ยนเรียนรู้'),
('PRJ2569-013', 'โครงการเสริมสร้างโอกาสและความเท่าเทียมทางการศึกษา ด้านทุนการศึกษา', '2569', 1, 7, 'ยังไม่เริ่ม', 0, 40735.00, 0.00, 'นักเรียนทุน 4 ประเภท', 'ดำเนินงานทุน, ลงพื้นที่เยี่ยมบ้านนักเรียน'),
('PRJ2569-014', 'โครงการแก้ไขปัญหาภาวะทุพโภชนาการ (จัดอาหารเช้ากรณีพิเศษ)', '2569', 1, 7, 'ยังไม่เริ่ม', 0, 5671800.00, 0.00, 'นักเรียน รร.พระราชดำริ 27 แห่ง จำนวน 1,325 คน', 'จัดซื้อจัดจ้างจัดทำอาหารเช้าพิเศษให้เด็กน้ำหนักต่ำกว่าเกณฑ์'),
('PRJ2569-015', 'โครงการพัฒนาคุณภาพการจัดการศึกษาเรียนรวม', '2569', 1, 2, 'ยังไม่เริ่ม', 0, 17780.00, 0.00, 'บุคลากรโรงเรียนจัดการศึกษาเรียนรวม', 'ประชุมปฏิบัติการผู้ดูแลระบบ SET'),
('PRJ2569-016', 'โครงการสร้างและส่งเสริมความเป็นพลเมืองดี ตามรอยพระยุคลบาท', '2569', 1, 7, 'ยังไม่เริ่ม', 0, 140000.00, 0.00, 'เด็กและเยาวชน 200 คน', 'เวิร์กช็อป, กิจกรรมจิตอาสา, ประกวดสื่อสร้างสรรค์'),

-- ยุทธศาสตร์ที่ 2 (11 โครงการ)
('PRJ2569-017', 'เพิ่มทักษะด้านอาชีพแก่นักเรียนที่ไม่ได้เรียนต่อหลังจบการศึกษาภาคบังคับ', '2569', 2, 13, 'ยังไม่เริ่ม', 0, 693600.00, 0.00, 'นักเรียน ม.3 ที่ไม่ได้เรียนต่อ 40 คน', 'ฝึกอบรมเตรียมเข้าทำงาน 280 ชม. และฝึกในสถานประกอบการ 1 เดือน'),
('PRJ2569-018', 'กิจกรรมการส่งเสริมอาชีพและการสร้างรายได้ในท้องถิ่น (ปอเนาะ)', '2569', 2, 5, 'ยังไม่เริ่ม', 0, 461200.00, 0.00, 'ผู้เรียนในสถาบันปอเนาะ 120 คน', 'ฝึกอบรมวิชาชีพระยะสั้น (ช่างไฟฟ้าและคหกรรม)'),
('PRJ2569-019', 'โครงการการขับเคลื่อนพื้นที่นวัตกรรมการศึกษาจังหวัดนราธิวาส', '2569', 2, 7, 'ยังไม่เริ่ม', 0, 0.00, 0.00, 'สถานศึกษานำร่อง 67 แห่ง', 'ค่ายพัฒนาผู้เรียน Startup, พัฒนาครูสอนสมรรถนะผู้ประกอบการ'),
('PRJ2569-020', 'โครงการพัฒนาทักษะอาชีพสู่การมีรายได้ระหว่างเรียน (Learn to Earn)', '2569', 2, 4, 'ยังไม่เริ่ม', 0, 7650.00, 0.00, 'โรงเรียนสังกัด สพม.นราธิวาส', 'ประกวดผลการปฏิบัติที่เป็นเลิศ Best Practice'),
('PRJ2569-021', 'พัฒนาระบบนิเวศทรัพย์สินทางปัญญาและยกระดับนวัตกรรมฮาลาล', '2569', 2, 14, 'ยังไม่เริ่ม', 0, 2000000.00, 0.00, 'นักวิจัย นักศึกษา 80 คน', 'พัฒนาหลักสูตร, แข่งขัน, สร้าง Platform, Business Matching'),
('PRJ2569-022', 'ยกระดับและพัฒนาสินค้าและบริการเศรษฐกิจฐานราก', '2569', 2, 15, 'ยังไม่เริ่ม', 0, 202600.00, 0.00, 'วิสาหกิจชุมชน 125 คน (10 กลุ่ม)', 'พัฒนาผลิตภัณฑ์, ส่งเสริมการตลาดดิจิทัล, ประชาสัมพันธ์ออนไลน์'),
('PRJ2569-023', 'สร้างจิตสานึกในการเป็นผู้ประกอบการและแผนธุรกิจ (SMEs อาชีวะ)', '2569', 2, 16, 'ยังไม่เริ่ม', 0, 10000.00, 0.00, 'นักเรียน ปวช.1 และ ปวส.1', 'อบรมเขียนแผนธุรกิจ, ประกวดและประเมินคัดเลือก'),
('PRJ2569-024', 'โครงการเพิ่มผลิตภาพแรงงานเพื่อยกระดับรายได้ให้พ้นเกณฑ์ความยากจน', '2569', 2, 17, 'ยังไม่เริ่ม', 0, 457600.00, 0.00, 'ผู้เปราะบาง/เยาวชน NEET 80 คน', 'ฝึกอบรมกลุ่มอาชีพ, ทำบรรจุภัณฑ์, ศึกษาดูงาน'),
('PRJ2569-025', 'พัฒนาและให้บริการแหล่งเรียนรู้ตลอดชีวิตด้านอาหาร', '2569', 2, 15, 'ยังไม่เริ่ม', 0, 189000.00, 0.00, 'ประชาชนผู้สนใจ 150 คน', 'จัดบริการแหล่งเรียนรู้ด้านอาหาร'),
('PRJ2569-026', 'ศูนย์เรียนรู้ผ้าปาเต๊ะ เพื่อการพัฒนาศักยภาพคนในพื้นที่', '2569', 2, 15, 'ยังไม่เริ่ม', 0, 237850.00, 0.00, 'ประชาชนผู้สนใจ 150 คน', 'อบรมทำแม่พิมพ์, ย้อมสีธรรมชาติ, เพ้นท์เฮนน่า'),
('PRJ2569-027', 'พัฒนาและให้บริการแหล่งเรียนรู้ด้านการแพทย์แผนไทยและทางเลือก', '2569', 2, 15, 'ยังไม่เริ่ม', 0, 454870.00, 0.00, 'ประชาชนผู้สนใจ 150 คน', 'อบรมผู้ช่วยแพทย์แผนไทย, นวดลังกาสุกะ, ทำลูกประคบ'),

-- ยุทธศาสตร์ที่ 3 (8 โครงการ)
('PRJ2569-028', 'พัฒนาคุณภาพของสถานศึกษาสู่มาตรฐาน OBECQA', '2569', 3, 4, 'ยังไม่เริ่ม', 0, 30000.00, 0.00, 'โรงเรียน 17 แห่ง', 'ประชุมเชิงปฏิบัติการ, นิเทศติดตามประเมินผล'),
('PRJ2569-029', 'ส่งเสริมกระบวนการเรียนรู้ผ่านดิจิทัลแพลตฟอร์ม', '2569', 3, 4, 'ยังไม่เริ่ม', 0, 11200.00, 0.00, 'ครูและผู้บริหาร', 'สร้างแพลตฟอร์ม, อบรม, เผยแพร่'),
('PRJ2569-030', 'พัฒนาหลักสูตรและการจัดประสบการณ์ตามหลักสูตรปฐมวัย 2568', '2569', 3, 1, 'ยังไม่เริ่ม', 0, 30570.00, 0.00, 'ครูแกนนำและครูผู้สอนปฐมวัย 137 คน', 'อบรมทำหลักสูตรและแผนประสบการณ์การเรียนรู้'),
('PRJ2569-031', 'Innovation For Thai Education (IFTE) นวัตกรรมการศึกษา', '2569', 3, 7, 'ยังไม่เริ่ม', 0, 180000.00, 0.00, 'โรงเรียนนำร่อง 14 แห่ง', 'ประชุมเสวนา, นำนวัตกรรมไปใช้พัฒนาทักษะ (Soft Power), ลงพื้นที่ PLC'),
('PRJ2569-032', 'หลักสูตรสถานศึกษาสู่ Active Learning โดยใช้ AI และแหล่งเรียนรู้', '2569', 3, 4, 'ยังไม่เริ่ม', 0, 9520.00, 0.00, 'ครูผู้สอนและผู้บริหาร', 'จัดทำกรอบหลักสูตรท้องถิ่น, ส่งเสริม Active Learning 8 กลุ่มสาระด้วย AI'),
